\begin{lemma}[Pohozaev inequality]
\label{lem-sub-002}
Let $u$ be a $C^2$-continuous subharmonic function on the unit disk.
Then the following integral along the boundary of a smaller disk $D_R$ for some $0< R <1$
can estimated as 
\begin{equation}
\label{sub-007}
\left| \int_{S^1} \left( |u_t|^2 - |\xi_0 u|^2 \right)  \right| \leq 2 L_A(u) \cdot \left( \int_{S^1} u_t \right), 
\end{equation}
where $A = -\log R$. 
\end{lemma}

\begin{corollary}
 Let $\{\eta\}$ and $\{\theta\}$ be big cohomology classes. Let $\phi\in\PSH(X,\theta)$. Then the following are equivalent.
\hfill
\begin{enumerate}
\item $\PSH(X,\eta)\cap\mathcal{E}(X,\theta,\phi)\neq \varnothing$.

\item There exists $u\in\PSH(X,\eta)$, $v\in\mathcal{E}(X,\theta,\phi)$, $c>0$, and $h\in\mathcal{E}(X,\omega)$ such that \[u\geq v+ ch. \]

\item $\mathcal{E}(X,\eta)\cap\PSH(X,\theta,\phi)\subset \mathcal{E}(X,\theta,\phi)$.
\end{enumerate}

\end{corollary}

\begin{proposition}\label{flat_family}
	Let $<$ be a monomial ordering on $\mathcal{O}_{\mathbb{C}^n, 0}$. Assume that $z^{\alpha^1}, \dots, z^{\alpha^k}$ are monomials in $\mathcal{O}_{\mathbb{C}^n, 0}$. Then there exists $a = (a_1, \dots, a_n) \in \mathbb{N}^n$ such that
	$$
	\inf\left\{ \sum_{i=1}^n a_i \beta_i : \beta \in \mathbb{N}^n,\ z^{\beta} > z^{\alpha^j} \right\}
	> \sum_{i=1}^n a_i \alpha_i^j,\quad \text{for all } 1 \leq j \leq k.
	$$
\end{proposition}

\begin{thm}\label{thm-q-Dirichlet-unbounded}
Let $r$, $q$, $D$ be as in Theorem~\ref{thm-q-Dirichlet}, except that $D$ is unbounded. Let $f \in \ccal(\partial D)$ with $0 \leq f \leq \sup_{\partial D} f \leq M$ for some upper bound $M < +\infty$. Then there exists an almost \qbrem\ \fct\ $\Phi=\Phi_M$ on $\cld$ such that

\begin{enumerate}

\item $\Phi=f$ on $\partial D$, and $0 \leq \Phi \leq M$ on $\cld$.

\item $\Phi$ is $q$-maximal with respect to \qpsh\ \fcts\ $\psi$ with $\psi \leq f$ on $\partial D$ and $\psi \leq M$ on $\cld$. Therefore, $\pcal_{f,q,D,M} \leq \Phi$.

\item $\Phi$ is \cont\ on $\partial D$.

\item If $D$ is of bounded type, $\Phi$ is \cont\ and \qbrem\ on $\cld$. Thus, $\Phi=\pcal_{f,q,D,M_0}$ for $M_0:=\sup_{\partial D} f$.

\item If $D$ is of bounded type, $\Phi$ is the unique \qbrem\ \fct\ on $\cld$ with $\Phi=f$ on $\partial D$.% and $0\leq \Phi \leq \sup_{\partial D} f$ on $\cld$.

\end{enumerate}

\end{thm}

\begin{theo}\label{thm:positive}
Let $\mu$ be a probability measure with countable support in $\SLk$, satisfying~\eqref{B1}. Then there exists a unique stationary probability measure $\nu$ on $\berk$, that is stationary under the action of $\mu$. This measure has no atoms, it is supported on the limit set of $\Gamma$, and when $k$ is non-Archimedean it gives full mass to $\PP^1(k)$ so that $\nu (\hh_k)=0$.

If furthermore~\eqref{B2} holds, then the Lyapunov exponent $\chi(\mu)$ of the associated random product of matrices is positive and satisfies the following formula
\begin{align}\label{eq:furstenberg}
\chi(\mu) & = \int \sigma(\gamma, v) \, \dmu(\gamma)\, \dnu(v).
\end{align}

Finally for $\prob$-a.e. $\omega$ and for $\nu$-a.e. $v$, we have:
\begin{align}
\chi(\mu) = \lim_{n\to\infty} \frac1n \log \sigma(\ell_n(\omega), v) \label{eq301}
.
\end{align}
\end{theo}

\begin{theorem}\label{thm:padic}
Assume that $X$ has an \snc-model.
\begin{enumerate}
\item \label{it:maintame} As~$K'$ ranges through $\mathcal{E}^t_K$, the measure $\nu^t_{\form,K'}$
converges to the stable Lebesgue measure $\Leb^{\rs}_{\Sk^t(X,\form)}$
supported on the temperate part of the Kontsevich--Soibelman skeleton of the pair $(X,\form)$.
\item \label{it:mainwild} If $X$ has a log smooth proper $R$\nobreakdash-model, then as~$K'$ ranges through $\mathcal{E}^a_K$, the measure $\nu_{\form,K'}$
converges to the stable Lebesgue measure $\Leb^{\rs}_{\Sk(X,\form)}$
supported on the Kontsevich--Soibelman skeleton of the pair $(X,\form)$.
\end{enumerate}
\end{theorem}

\begin{lem}\label{lem:CharacRelativiStabel}
Take any $U\Subset V\Subset \R^d$. 
\begin{enumerate}
\item[\rm(1)] There exists $C_2=C_2(d,\alpha,m,U,V)>0$ such that for any $x\in U$ and $y\in V$, 
\begin{align*}
\frac{\Psi(m^{\frac{1}{\alpha}}|x-y|)}{|x-y|^{d+\alpha}}\leq C_2\Psi(m^{\frac{1}{\alpha}}|y|)\left(1\land\frac{1}{|y|^{d+\alpha}} \right).
\end{align*}
\item[\rm(2)] Suppose $0\in V$. There exists $C_1=C_1(d,\alpha,m,U,V)>0$ such that for any $x\in U$ and $y\in V$,
\begin{align*}
\frac{\Psi(m^{\frac{1}{\alpha}}|x-y|)}{|x-y|^{d+\alpha}}\geq C_1
\Psi(m^{\frac{1}{\alpha}}|y|)
\left(1\land\frac{1}{|y|^{d+\alpha}}\right).
\end{align*}
\item[\rm(3)] 
For each $x_0\in\R^d$, 
$\Psi(m^{\frac{1}{\alpha}}|\cdot-x_o|)\left(1\land\frac{1\;\,}{|\,\cdot-x_o\,|^{d+\alpha}} \right)\in L^1(\R^d)\cap L^2(\R^d)$.
\end{enumerate}
\end{lem}

\begin{lemm}\label{ddbars}{\it The endomorphism $s$ satisfies the following inequality in the sense of the distribution:
\begin{align}
\inum\partial\bar{\partial} \sum_{j=1}^rs_j\geq \sum_{j=1}^rs_{j-1}^{-1}(s_{j-1}-s_j)^2\vol(H_{j-1}). \label{s}
\end{align}
}
\end{lemm}

